package thaumcraft.datagen;
import com.google.gson.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class WearableAssetsTest {
    @Test void allThirtySnapshotPayloadsMatchAndTheirTexturesResolve() throws Exception {var manifest=JsonParser.parseString(Files.readString(Path.of("src/main/resources",TCWearableAssetsProvider.RESOURCE))).getAsJsonObject();TCWearableAssetsProvider.validate(manifest);assertEquals(30,manifest.getAsJsonArray("entries").size());for(var entry:manifest.getAsJsonArray("entries")){var row=entry.getAsJsonObject();var payload=row.getAsJsonObject("payload");assertEquals(payload,JsonParser.parseString(Files.readString(Path.of("src/generated/resources",row.get("path").getAsString()))));if(payload.has("textures"))for(var texture:payload.getAsJsonObject("textures").entrySet()){String id=texture.getValue().getAsString();assertTrue(id.startsWith("thaumcraft:item/"),id);assertTrue(Files.isRegularFile(Path.of("src/main/resources/assets/thaumcraft/textures",id.substring("thaumcraft:".length())+".png")),id);}}}
    @Test void sourceFortressGeometryIncludesAllMasksAndExactOriginalHash() throws Exception {var geometry=JsonParser.parseString(Files.readString(Path.of("src/main/resources/assets/thaumcraft/armor_geometry/fortress.json"))).getAsJsonObject();assertEquals(66,geometry.getAsJsonArray("parts").size());var source=Path.of("../reference/tc6/src/thaumcraft/client/renderers/models/gear/ModelFortressArmor.java");assertEquals(HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(source))),geometry.get("sha256").getAsString());var names=new HashSet<String>();for(var part:geometry.getAsJsonArray("parts"))names.add(part.getAsJsonObject().get("name").getAsString());assertTrue(names.containsAll(List.of("Mask0","Mask1","Mask2","Goggles","Book","Scroll")));}
    @Test void dyeLayerOrderAndCuriosGenuineSlotsStaySourceBacked() throws Exception {var cloth=JsonParser.parseString(Files.readString(Path.of("src/generated/resources/assets/thaumcraft/models/item/cloth_chest.json"))).getAsJsonObject();var robe=JsonParser.parseString(Files.readString(Path.of("src/generated/resources/assets/thaumcraft/models/item/void_robe_chest.json"))).getAsJsonObject();assertEquals("thaumcraft:item/cloth_chest",cloth.getAsJsonObject("textures").get("layer0").getAsString());assertEquals("thaumcraft:item/void_robe_chest_over",robe.getAsJsonObject("textures").get("layer0").getAsString());var head=JsonParser.parseString(Files.readString(Path.of("src/generated/resources/data/curios/tags/item/head.json"))).getAsJsonObject();assertEquals(2,head.getAsJsonArray("values").size());var charm=JsonParser.parseString(Files.readString(Path.of("src/generated/resources/data/curios/tags/item/charm.json"))).getAsJsonObject();assertEquals(3,charm.getAsJsonArray("values").size());}
}
